import json

# Load Patient data
with open('json/Patient.json', 'r') as f:
    patient_data = json.load(f)
patients = patient_data['records']

# Load Examination data
with open('json/Examination.json', 'r') as f:
    exam_data = json.load(f)
examinations = exam_data['records']

# Create a lookup dict for examinations by ID
exam_by_id = {}
for exam in examinations:
    pid = exam['ID']
    if pid not in exam_by_id:
        exam_by_id[pid] = []
    exam_by_id[pid].append(exam)

# Find patients with severe thrombosis (Thrombosis=2)
result = []
for patient in patients:
    pid = patient['ID']
    if pid in exam_by_id:
        for exam in exam_by_id[pid]:
            if exam.get('Thrombosis') == 2:
                result.append({
                    'ID': patient['ID'],
                    'SEX': patient['SEX'],
                    'Diagnosis': patient['Diagnosis']
                })
                break  # Only include each patient once

print(f"Found {len(result)} patients with severe thrombosis")
for r in result[:5]:
    print(r)
